CREATE TABLE public.booking_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), reference text NOT NULL UNIQUE, kind text NOT NULL DEFAULT 'availability', full_name text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', check_in date, check_out date, adults integer NOT NULL DEFAULT 1 CHECK (adults >= 1), children integer NOT NULL DEFAULT 0 CHECK (children >= 0), rooms integer NOT NULL DEFAULT 1 CHECK (rooms >= 1), room_category text NOT NULL DEFAULT 'Sans préférence', company text NOT NULL DEFAULT '', message text NOT NULL DEFAULT '', consent boolean NOT NULL, status text NOT NULL DEFAULT 'awaiting_hotel_confirmation', CHECK (check_out IS NULL OR check_out > check_in), CHECK (consent = true)); GRANT ALL ON public.booking_requests TO service_role; ALTER TABLE public.booking_requests ENABLE ROW LEVEL SECURITY;